<?php
header('Content-Type: application/json');require_once __DIR__.'/../config/response.php';require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../config/audit.php';require_once __DIR__.'/../auth/auth_required.php';require_once __DIR__.'/../auth/role_helper.php';require_once __DIR__.'/fiscal_result_service.php';require_once __DIR__.'/report_error.php';
try{if($_SERVER['REQUEST_METHOD']!=='POST')jsonResponse(['success'=>false,'message'=>'Method not allowed'],405);$auth=requireAuth();$uid=authTenantId($auth);$actorId=authActorId($auth);$d=json_decode(file_get_contents('php://input'),true)?:[];$year=(int)($d['year']??0);$type=strtoupper(trim((string)($d['adjustment_type']??'')));$timing=strtoupper(trim((string)($d['timing']??'')));$category=trim((string)($d['category']??''));$description=trim((string)($d['description']??''));$amount=round((float)($d['amount']??0),3);$legal=trim((string)($d['legal_basis']??''));$notes=trim((string)($d['notes']??''));
    if($year<2000||$year>2200||!in_array($type,['ADDITION','DEDUCTION'],true)||!in_array($timing,['PERMANENT','TEMPORARY'],true)||$category===''||$description===''||$legal===''||$amount<=0)throw new InvalidArgumentException('Year, type, timing, category, description, positive amount, and legal basis are required');$conn=db();requirePermission($conn,$uid,'reports.view');$conn->begin_transaction();$source=operationalAccountingResult($conn,$uid,$year);$s=$conn->prepare("INSERT INTO erp_fiscal_reconciliations(user_id,fiscal_year,accounting_result,accounting_source,status,created_by) VALUES(?,?,?,'OPERATIONAL_LEDGER','DRAFT',?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)");$s->bind_param('iidi',$uid,$year,$source['result'],$actorId);$s->execute();$rid=(int)$s->insert_id;$s->close();$s=$conn->prepare('SELECT status FROM erp_fiscal_reconciliations WHERE id=? AND user_id=? FOR UPDATE');$s->bind_param('ii',$rid,$uid);$s->execute();$header=$s->get_result()->fetch_assoc();$s->close();if(!$header||$header['status']!=='DRAFT')throw new DomainException('Only draft fiscal reconciliations can be edited');$s=$conn->prepare("UPDATE erp_fiscal_reconciliations SET accounting_result=? WHERE id=? AND user_id=? AND accounting_source='OPERATIONAL_LEDGER'");$s->bind_param('dii',$source['result'],$rid,$uid);$s->execute();$s->close();
    $s=$conn->prepare('INSERT INTO erp_fiscal_adjustments(reconciliation_id,user_id,adjustment_type,timing,category,description,amount,legal_basis,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?)');$s->bind_param('iissssdssi',$rid,$uid,$type,$timing,$category,$description,$amount,$legal,$notes,$actorId);$s->execute();$id=(int)$s->insert_id;$s->close();auditLog($conn,$uid,$actorId,'FISCAL_ADJUSTMENT.ADDED','FISCAL_ADJUSTMENT',$id,null,['fiscal_year'=>$year,'adjustment_type'=>$type,'timing'=>$timing,'category'=>$category,'description'=>$description,'amount'=>$amount,'legal_basis'=>$legal]);$conn->commit();jsonResponse(['success'=>true,'id'=>$id,'reconciliation_id'=>$rid,'accounting_result'=>$source['result']]);
}catch(Throwable $e){if(isset($conn))try{$conn->rollback();}catch(Throwable $ignored){}reportFailureResponse($e,'Could not save the fiscal adjustment.','FISCAL_ADJUSTMENT_SAVE_FAILED');}
